            if i > 0 && nums[i] == nums[i - 1] {
                continue;
            }
            for j in (i + 1)..n {
                *count.get_mut(&nums[j]).unwrap() -= 1;
                if j > i + 1 && nums[j] == nums[j - 1] {
                    continue;
